insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('vector-search-fundamentals','vector-search-fundamentals','חיפוש וקטורי — יסודות ובחירת אחסון','concept','חיפוש וקטורי מאחזר פריטים לפי דמיון לייצוג מספרי. הפרק מלמד לבחור בין חיפוש מדויק, ANN, מסד SQL, מסד ייעודי ושירות חיפוש, ולהעריך איכות, סינון ותפעול לפני הוספת תשתית.','published','verified','2026-11-02',1,'יישום הדוח המאושר vector05-20261102-v1. מקורות רשמיים, דוגמאות ותרגילים מוצעים שלא הורצו; אין מדידת ביצועים או שוויון SDKs.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved vector05-20261102-v1 V05-01–V05-08 including Chroma and Qdrant corrections; docs/DECISIONS.md D-033');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('pgvector','pgvector','pgvector','database','הרחבת PostgreSQL לשמירת וקטורים וחיפוש דמיון מדויק או מקורב לצד נתונים רלציוניים. מאפשרת לבחון SQL, קשרים וסינון באותו מסד לפני שמוסיפים מערכת אחסון נפרדת.','published','verified','2026-11-02',1,'יישום הדוח המאושר vector05-20261102-v1. מקורות רשמיים, דוגמאות ותרגילים מוצעים שלא הורצו; אין מדידת ביצועים או שוויון SDKs.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved vector05-20261102-v1 V05-01–V05-08 including Chroma and Qdrant corrections; docs/DECISIONS.md D-033');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('azure-ai-search','azure-ai-search','Azure AI Search','platform','שירות חיפוש מנוהל של Microsoft לשילוב חיפוש טקסטואלי, וקטורי ומשולב. תומך באינדוקס ושליפה ליישומים ארגוניים ואינו רק מאגר embeddings או שם נוסף ל־Azure OpenAI.','published','verified','2026-11-02',1,'יישום הדוח המאושר vector05-20261102-v1. מקורות רשמיים, דוגמאות ותרגילים מוצעים שלא הורצו; אין מדידת ביצועים או שוויון SDKs.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved vector05-20261102-v1 V05-01–V05-08 including Chroma and Qdrant corrections; docs/DECISIONS.md D-033');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('weaviate','weaviate','Weaviate','database','מסד נתונים לחיפוש וקטורי ומשולב עם אובייקטים, סינון ואינטגרציות למודלים. מציע מסלולי אירוח עצמי וענן; יש להבחין בין ליבה, תוספות Enterprise ותמיכת לקוחות לפי גרסה.','published','verified','2026-11-02',1,'יישום הדוח המאושר vector05-20261102-v1. מקורות רשמיים, דוגמאות ותרגילים מוצעים שלא הורצו; אין מדידת ביצועים או שוויון SDKs.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved vector05-20261102-v1 V05-01–V05-08 including Chroma and Qdrant corrections; docs/DECISIONS.md D-033');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('milvus','milvus','Milvus','database','מסד וקטורי בקוד פתוח עם אפשרויות פריסה מקומיות ומבוזרות. מספק הזדמנות ללמוד הפרדת חיפוש ואחסון בעומסים גדולים, תוך הבחנה בין Milvus לבין שירות Zilliz Cloud וגרסאות לקוח שונות.','published','verified','2026-11-02',1,'יישום הדוח המאושר vector05-20261102-v1. מקורות רשמיים, דוגמאות ותרגילים מוצעים שלא הורצו; אין מדידת ביצועים או שוויון SDKs.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved vector05-20261102-v1 V05-01–V05-08 including Chroma and Qdrant corrections; docs/DECISIONS.md D-033');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('pinecone','pinecone','Pinecone','platform','שירות מסד וקטורי מנוהל המבוסס על API, עם אינדקסים ונתוני metadata לשליפה. חשוב להשוות את הפחתת התפעול לעלות ולתלות בספק; תמיכת SDK משתנה בנפרד ממצב השירות.','published','verified','2026-11-02',1,'יישום הדוח המאושר vector05-20261102-v1. מקורות רשמיים, דוגמאות ותרגילים מוצעים שלא הורצו; אין מדידת ביצועים או שוויון SDKs.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved vector05-20261102-v1 V05-01–V05-08 including Chroma and Qdrant corrections; docs/DECISIONS.md D-033');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('chroma','chroma','Chroma','database','מערכת אחסון ושליפה עם מסלולים מקומיים, שרת ו־Cloud. מספקת ניגוד שימושי למסד מבוזר או לשירות חיפוש ארגוני; אין לצמצמה לצעצוע בזיכרון או להניח שכל יכולת זמינה בכל מסלול.','published','verified','2026-11-02',1,'יישום הדוח המאושר vector05-20261102-v1. מקורות רשמיים, דוגמאות ותרגילים מוצעים שלא הורצו; אין מדידת ביצועים או שוויון SDKs.','2026-11-02','approved_proposal','2026-11-02','2026-11-02','User approved vector05-20261102-v1 V05-01–V05-08 including Chroma and Qdrant corrections; docs/DECISIONS.md D-033');
insert into academy.entry_categories (entry_id,category_id,position) values ('vector-search-fundamentals','05',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('vector-search-fundamentals','היכרות עם SQL, REST, אינדקסים והרשאות; לכלי מוצר מומלץ להתחיל ביסודות החיפוש הווקטורי.','תרחיש לימודי מוצע שלא הורץ: פורטל נהלים ב־ASP.NET Core משווה חיפוש טקסטואלי, pgvector ו־Qdrant על אותו אוסף ושאלות. בוחרים במסלול הפשוט שעומד באיכות, הרשאות וזמן תגובה; אם SQL רגיל מספיק אין צורך במסד וקטורי נוסף.','תכננו baseline מדויק וניסוי ANN על אותם נתונים. בדקו recall, סינון ארגון, מחיקה, שינוי מודל embeddings ועלות תפעול; שנו פרמטר אחד בכל פעם.','העקרונות אינם תלויים בשפה: אפשר ליישם C#/.NET, Python או TypeScript. יש לבדוק SDK וגרסאות לכל מוצר בנפרד; לקוח HTTP אינו SDK מקומי ואינו מבטיח שוויון יכולות.','הפרק אינו המלצה להעביר את מסד האקדמיה לחיפוש וקטורי. בחרו לפי צורך אמיתי: SQL וטקסט, הרחבת SQL, מסד ייעודי או שירות חיפוש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('vector-search-fundamentals',0,'מייצוג לחיפוש','Embedding הוא וקטור של מודל מסוים. שומרים מזהה יציב, גרסה ו־metadata, ומחשבים לשאילתה ייצוג תואם. דמיון מספרי אינו הוכחה לאמת או להרשאת גישה; אין לערבב מרחבי embeddings שונים בלי תכנון מעבר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('vector-search-fundamentals',1,'חיפוש מדויק לעומת ANN','חיפוש מדויק הוא baseline שימושי. ANN כגון HNSW או IVFFlat מחליף חלק מהדיוק בזמן ובמשאבים; בחירה תלויה בנפח, בסינון ובעדכונים. בדקו recall מול תוצאות baseline, זמן תגובה ועלות זיכרון בלי להניח שאינדקס תמיד עדיף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('vector-search-fundamentals',2,'סינון וחיפוש משולב','Dense מתאים לדמיון סמנטי; התאמה מילולית או sparse יכולה לשמר שמות, קודים ומונחים. Hybrid ממזג מסלולי שליפה, ו־reranking הוא שלב נפרד. סינון tenant והרשאות חייב להיגזר מהשרת, ויש לבדוק את השפעתו על תוצאות ANN.');
insert into academy.entry_sections (entry_id,position,title,body) values ('vector-search-fundamentals',3,'בחירה לפי המערכת הקיימת','pgvector מוסיפה יכולת ל־PostgreSQL; Qdrant, Weaviate ו־Milvus הם מסדים ייעודיים; Azure AI Search היא מערכת חיפוש מנוהלת; FAISS היא ספריית אינדקס ולא מסד עם הרשאות ותפעול מלא. SQL או חיפוש טקסטואלי עשויים להספיק בלי embeddings.');
insert into academy.entry_sections (entry_id,position,title,body) values ('vector-search-fundamentals',4,'המסלול של SQL Server ו־NET','Microsoft.Data.SqlClient מציעה SqlVector<T>. אין להסיק מסוג vector שאינדקס ANN יציב בכל מוצר: VECTOR_SEARCH ואינדקסיו GA ב־Azure SQL/Fabric וב־MI במסלול Always-up-to-date, אך Preview ב־SQL Server 2025 וב־MI במסלול 2025 לפי המקור שנבדק. בדקו את גרסת השרת והלקוח לפני בחירה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('vector-search-fundamentals',5,'מחזור חיים והערכה','מדדו שאלות עם תשובות צפויות, מסננים מצמצמים, מסמך שנמחק ושינוי הרשאה. הגדירו מי מחולל embeddings, איך מסנכרנים מקור ואינדקס ומה קורה בכשל חלקי. Stars הם עניין קהילתי ואינם מדד recall, תחזוקה מובטחת או נתח שוק.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('vector-search-fundamentals','must_learn','חובה להבין דמיון, סינון ו־recall לפני בחירת מסד או העברת מידע ארגוני למנוע חיפוש.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('vector-search-fundamentals','יסודות חיפוש וקטורי, ANN וחיפוש משולב; בחירת אחסון לפי איכות, סינון ועלות תפעול.','העקרונות אינם תלויים בשפה: אפשר ליישם C#/.NET, Python או TypeScript. יש לבדוק SDK וגרסאות לכל מוצר בנפרד; לקוח HTTP אינו SDK מקומי ואינו מבטיח שוויון יכולות.','not_applicable','פרק מושגים ללא מאגר מוצר מייצג.','2026-11-02');
insert into academy.entry_language_labels (entry_id,position,label) values ('vector-search-fundamentals',0,'לא תלוי בשפה');
