insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('pgvector','היכרות עם SQL, REST, אינדקסים והרשאות; לכלי מוצר מומלץ להתחיל ביסודות החיפוש הווקטורי.','תרחיש מוצע שלא הורץ: למערכת רכש ב־ASP.NET Core כבר יש PostgreSQL. שומרים chunks של נהלים עם document_id ו־tenant_id ומשווים חיפוש exact ל־HNSW דרך Npgsql. בוחרים pgvector כשהיא עומדת במדדים ומפשטת קשרים; אם שליפה כבדה פוגעת בטרנזקציות או חסרה יכולת נדרשת, משווים ל־Qdrant נפרדת.','תכננו טבלה, מחיקה וסינון הרשאות, ואז השוו exact ו־ANN עם אותם מסננים. מדדו recall ועומס על הפעילות העסקית.','ההרחבה פועלת בתוך PostgreSQL ואינה שרת Python. הפרויקט מפרסם pgvector-dotnet ל־C#/.NET עם Npgsql, Dapper ו־EF Core; יש חיבורים ל־Python ול־JavaScript/TypeScript. תאימות הלקוח, ההרחבה והשרת דורשת בדיקה לפי גרסה.','Qdrant/Weaviate/Milvus מציעות מסד ייעודי; Azure AI Search מוסיפה שכבת חיפוש מנוהלת. אל תוסיפו שירות אם PostgreSQL או חיפוש מילולי מספיקים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pgvector',0,'הרחבה ולא מסד עצמאי','עמודת vector נשמרת בטבלה לצד מזהי מסמכים, גרסאות ו־metadata. שאילתת דמיון מצטרפת למידע עסקי באמצעות SQL. הסיווג database מתייחס לתפקיד האחסון; מדובר בהרחבת PostgreSQL ולא במוצר שרת נפרד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pgvector',1,'אינדקסים וסינון','הפרויקט תומך בחיפוש מדויק וב־HNSW/IVFFlat. יש למדוד תוצאות אחרי סינון, לבחור אינדקס ופרמטרים ולהסתכל על תוכנית ביצוע. ANN אינו מבטיח אותם שכנים כמו baseline מדויק, ו־joins לבדם אינם פותרים את כל עלויות השליפה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pgvector',2,'בחירה מעשית מול מסד ייעודי','בחרו כשיש PostgreSQL קיים ורוצים טרנזקציות, קשרים ופחות מערכות לסנכרן. בחנו Qdrant או Milvus אם העומס והדרישות מצדיקים בידוד משאבי חיפוש או יכולות ייעודיות. אין כאן הבטחה ליתרון ביצועים של מוצר אחד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pgvector',3,'גרסאות ורישוי','Changelog שנבדק מתעד 0.8.7 מאוקטובר 2026, ו־0.9.0 כ־unreleased. אין להשתמש בתכונות ענף הפיתוח כאילו פורסמו. רישיון ההרחבה בנוסח PostgreSQL ולקוח .NET הוא MIT; שירותי אירוח כפופים לתנאיהם.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pgvector',4,'תפעול, גישה ומחיקה','צריך להפעיל הרשאות SQL מתאימות ולבדוק כיצד הסינון נאכף ביישום. מחיקת מסמך מחייבת מחיקת וקטורים תואמים. תכננו גיבוי, שינוי ממדי embeddings, גדילת אינדקס ותחרות על משאבים עם שאילתות עסקיות.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('pgvector','should_know','נקודת פתיחה מעשית למפתח SQL/.NET: לבדוק חיפוש וקטורי בלי להוסיף אוטומטית מסד נפרד.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('pgvector','הרחבת PostgreSQL לחיפוש וקטורי מדויק ו־ANN, לצד SQL וקשרים קיימים.','ההרחבה פועלת בתוך PostgreSQL ואינה שרת Python. הפרויקט מפרסם pgvector-dotnet ל־C#/.NET עם Npgsql, Dapper ו־EF Core; יש חיבורים ל־Python ול־JavaScript/TypeScript. תאימות הלקוח, ההרחבה והשרת דורשת בדיקה לפי גרסה.','verified','המאגר הראשי של הפרויקט בלבד. צילום המחקר המאושר, לא דירוג איכות.','2026-11-02');
