insert into academy.entry_categories (entry_id,category_id,position) values ('azure-ai-search','05',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('azure-ai-search','היכרות עם SQL, REST, אינדקסים והרשאות; לכלי מוצר מומלץ להתחיל ביסודות החיפוש הווקטורי.','תרחיש מוצע שלא הורץ: ארגון שמפעיל .NET ב־Azure רוצה לחפש נהלים לפי מספר נוהל וגם ניסוח חופשי. ה־API משתמש ב־Azure.Search.Documents לשאילתת hybrid עם מסנן ארגון. בוחרים בשירות כדי לצמצם תפעול חיפוש; אם המסמכים מעטים ונמצאים ב־PostgreSQL, משווים קודם pgvector וחיפוש טקסטואלי.','תכננו אינדקס עם מזהה מסמך, גרסה, tenant וטקסט/וקטור. השוו keyword, vector ו־hybrid ובדקו מחיקה ושינוי הרשאות.','יש SDK רשמי ל־C#/.NET בשם Azure.Search.Documents, לצד Python, JavaScript/TypeScript ו־Java ו־REST. התמיכה היא בשירות חיפוש מרוחק, לא במנוע מקומי שמוטמע ביישום. בדקו API version ותאימות כל דוגמה.','Pinecone מייצגת מסד מנוהל ייעודי; Qdrant/Weaviate מאפשרות מסלול עצמאי; pgvector עשויה להספיק בתוך SQL. הבדלי עלות, רישוי ומכסות מחייבים בדיקה לפני רכישה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('azure-ai-search',0,'תפקיד השירות','אינדקס מחזיק שדות טקסט, וקטורים ונתונים לסינון. היישום שולח שאילתה ומקבל תוצאות; יצירת תשובה ממודל היא שלב נוסף. השירות אינו זהה ל־Foundry או Azure OpenAI, גם כשהם משתלבים באותה מערכת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('azure-ai-search',1,'חיפוש משולב ואינדוקס','אפשר לשלב שאילתות keyword ו־vector ולמזג תוצאות. יכולות אינדוקס ו־vectorization משולבות דורשות הגדרות ומקורות נתמכים; יש לבדוק מתי היישום יוצר embeddings ומתי השירות קורא לספק מודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('azure-ai-search',2,'מתי לבחור ומתי חלופה','מתאים לצוות Azure שרוצה חיפוש ארגוני מנוהל ושילוב lexical/vector. כשכל המידע והקשרים ב־PostgreSQL והדרישות פשוטות, pgvector עשויה לצמצם שירותים; כשנדרשת שליטה במנוע או אירוח עצמי, בחנו Qdrant/Weaviate.');
insert into academy.entry_sections (entry_id,position,title,body) values ('azure-ai-search',3,'עלות ומהדורות','זהו שירות מסחרי עם קיבולת, מכסות ותכונות תלויות מסלול וגרסה. אין להסיק מתיעוד Cloud רישיון ליבת מסד פתוח או לחשב Stars ממאגר דוגמאות. עלות בפועל לא נמדדה במסגרת הפרק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('azure-ai-search',4,'הרשאות ומחזור חיים','זהות גישה לשירות אינה לבדה הרשאה לכל מסמך. סננו מקורות לפי המשתמש והארגון ובדקו מחיקות, עדכוני אינדקס ועיכוב סנכרון. ודאו מה נשלח ל־embedding ול־reranking חיצוניים.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('azure-ai-search','should_know','כדאי להכיר מסלול חיפוש ארגוני מנוהל עם חיבור .NET, ולהשוות עלות ותפעול למסד ייעודי.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('azure-ai-search','שירות חיפוש מנוהל עם שליפה טקסטואלית, וקטורית ומשולבת ליישומים ארגוניים.','יש SDK רשמי ל־C#/.NET בשם Azure.Search.Documents, לצד Python, JavaScript/TypeScript ו־Java ו־REST. התמיכה היא בשירות חיפוש מרוחק, לא במנוע מקומי שמוטמע ביישום. בדקו API version ותאימות כל דוגמה.','not_applicable','שירות מנוהל ללא מאגר ליבת מסד ציבורי מייצג; אין מדידה ממאגר SDK או דוגמאות.','2026-11-02');
