insert into academy.entry_categories (entry_id,category_id,position) values ('weaviate','05',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('weaviate','היכרות עם SQL, REST, אינדקסים והרשאות; לכלי מוצר מומלץ להתחיל ביסודות החיפוש הווקטורי.','תרחיש מוצע שלא הורץ: קטלוג חלקי חילוף צריך התאמה למק״ט ולתיאור חופשי, עם סינון לפי אתר. צוות .NET בוחן Weaviate.Client עם hybrid על collections. בוחרים כשמודל האובייקטים והחיפוש מצדיקים שירות ייעודי; כש־joins עסקיים שולטים בדרישה, משווים pgvector לפני סנכרון מידע למסד נוסף.','תכננו collection וסינון אתר, וקבעו גרסאות שרת/לקוח תואמות. השוו hybrid ל־Qdrant ו־SQL על אותן שאלות ותחזקו בדיקת מחיקה.','לקוחות רשמיים ל־Python, JavaScript/TypeScript, Java, Go ו־C#/.NET. Weaviate.Client 1.2.0 שנבדקה דורשת שרת 1.32 ומעלה וגישה ל־gRPC. אין להציג את C# כ־HTTP בלבד או להבטיח שכל יכולת זהה בכל שפה.','Qdrant ו־Milvus הן חלופות ייעודיות; Azure AI Search מספקת שכבת חיפוש מנוהלת רחבה; pgvector מצמצמת מערכות כש־SQL מספיק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('weaviate',0,'איך עובד האחסון','מגדירים collections ושדות אובייקט, ייצוגים וקטוריים ואפשרויות אינדוקס. בחירת vectorizer וקשר למודל נפרדים מאיכות המקור; יש להבין מי מפיק embeddings ומתי יוצא מידע החוצה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('weaviate',1,'חיפוש וסינון','השוו חיפוש dense לחיפוש משולב עם רכיב מילולי וסינון metadata. שיפור דירוג דורש ניסוי על שאלות ונתונים מתאימים, לא הסתמכות על טענת ספק. אין להסיק שהוספת מודול מחליפה בדיקות הרשאות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('weaviate',2,'מתי לבחור ומתי חלופה','מתאים לבחינת חיפוש אובייקטים משולב ואינטגרציות כשמוכנים להפעיל שירות ייעודי או Cloud. אם SQL וקשרים עסקיים הם המרכז, בדקו pgvector; אם רוצים להשוות מנוע ייעודי ו־API אחר, בחנו Qdrant על אותו עומס.');
insert into academy.entry_sections (entry_id,position,title,body) values ('weaviate',3,'רישוי ושכבות מוצר','LICENSE הנוכחי מפצל: BSD-3-Clause לקוד מחוץ ל־wl/ ורישיון Enterprise נפרד לקוד שבתוכה. אין לתאר את כל המאגר כ־BSD או להניח שתכונת Cloud נכללת בכל פריסה. לפני שימוש בדקו מהדורה ותכונות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('weaviate',4,'תאימות ותפעול','ללקוח C# שנבדק דרישת gRPC ושרת 1.32+. יש לקבע גרסאות ולתכנן schema, גיבוי, משאבים ועדכונים. מדריך ישן ללקוח או ל־GraphQL אינו בהכרח המסלול העדכני לפרויקט חדש.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('weaviate','should_know','חלופה חשובה להשוואת מסד ייעודי, חיפוש hybrid ואינטגרציות מול Qdrant, עם SDK .NET רשמי.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('weaviate','מסד לחיפוש וקטורי ומשולב עם אובייקטים וסינון; כולל SDK רשמי ל־C#.','לקוחות רשמיים ל־Python, JavaScript/TypeScript, Java, Go ו־C#/.NET. Weaviate.Client 1.2.0 שנבדקה דורשת שרת 1.32 ומעלה וגישה ל־gRPC. אין להציג את C# כ־HTTP בלבד או להבטיח שכל יכולת זהה בכל שפה.','verified','המאגר הראשי של הפרויקט בלבד. צילום המחקר המאושר, לא דירוג איכות.','2026-11-02');
