insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('milvus','היכרות עם SQL, REST, אינדקסים והרשאות; לכלי מוצר מומלץ להתחיל ביסודות החיפוש הווקטורי.','תרחיש מוצע שלא הורץ: צוות אחזור ארגוני מבודד חיפוש embeddings ממסדי העסק ומצפה לגידול משמעותי בכתיבות ובאוספים. הוא משווה Milvus בפריסה מתאימה מול Qdrant ומול PostgreSQL דרך API .NET. בוחרים Milvus רק אם היכולות והמדידות מצדיקות את התפעול; לאוסף קטן וקשרים רבים עדיפה תחילה בדיקת pgvector.','תכננו API ל־upsert/search/delete ובדיקות סינון ותאימות Milvus.Client.V2. השוו תפעול מקומי למבוזר בלי לטעון לביצועים שלא נמדדו.','יש SDKs רשמיים למספר שפות, כולל Python, Node.js/TypeScript, Java, Go ו־C++. מאגר C# מתעד Milvus.Client.V2 נוכחי למסלול .NET 8; גרסת לקוח 3.0.0 מותאמת ל־Milvus 3.0.x. Milvus.Client V1 היא מסלול היסטורי; אין להסיק ממנו שאין תמיכת .NET נוכחית.','Qdrant/Weaviate למסד ייעודי, pgvector ל־SQL, Pinecone או Zilliz Cloud למסלול מנוהל. אין צורך ברשומת Zilliz נוספת כדי להסביר את ההבדל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('milvus',0,'מסד ופריסות','Milvus מנהלת נתוני וקטורים, סינון ואינדקסים. קיימים מסלולים מקומיים ומבוזרים; אין לזהות את כל המוצר עם אשכול כבד, אך בפריסה מבוזרת צריך להבין את הרכיבים ואת הפרדת האחריות ביניהם.');
insert into academy.entry_sections (entry_id,position,title,body) values ('milvus',1,'עומס ואיכות','הגדירו סוגי embeddings, תדירות כתיבה, סינון ודרישות latency/recall. גודל מערכת לבדו אינו סיבה לבחירת מנוע; בחנו משאבי אינדקס, רעננות תוצאות ועלויות פעולה על אותו תרחיש מול חלופה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('milvus',2,'מתי לבחור ומתי חלופה','מתאים לבחינת שירות וקטורי ייעודי עם מסלול גדילה ומדיניות תפעול מפורשת. עבור אוסף קטן ביישום PostgreSQL, pgvector עשויה להיות פשוטה יותר; Qdrant היא השוואה שימושית למסד ייעודי אחר, ו־Zilliz Cloud מחליפה חלק מהתפעול בשירות מנוהל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('milvus',3,'SDK נוכחי לעומת היסטורי','Milvus.Client.V2 היא לקוח C# הנוכחי שנבדק; הוראות V1 הישנות אינן מקור אוטומטי לתאימות. בחרו גרסת SDK ושרת יחד. יעד .NET מתועד אינו מבטיח שוויון בכל התכונות ל־Python או לכל framework ישן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('milvus',4,'רישיון ותפעול','שרת Milvus הוא Apache-2.0; שירות Zilliz Cloud כפוף לתנאים נפרדים. נדרשים תכנון גיבוי, הרשאות, שחזור וגרסאות אינדקס. Stars במאגר Milvus אינם סכום של SDKs ושירות הענן ואינם מדד איכות חיפוש.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('milvus','should_know','כדאי להכיר להשוואת פריסות מסד וקטורי ודרישות תפעול, בלי להקים אשכול מורכב לפני שיש צורך.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('milvus','מסד וקטורי עם פריסות מקומיות ומבוזרות ו־SDK C# נוכחי מסוג V2.','יש SDKs רשמיים למספר שפות, כולל Python, Node.js/TypeScript, Java, Go ו־C++. מאגר C# מתעד Milvus.Client.V2 נוכחי למסלול .NET 8; גרסת לקוח 3.0.0 מותאמת ל־Milvus 3.0.x. Milvus.Client V1 היא מסלול היסטורי; אין להסיק ממנו שאין תמיכת .NET נוכחית.','verified','המאגר הראשי של הפרויקט בלבד. צילום המחקר המאושר, לא דירוג איכות.','2026-11-02');
