insert into academy.entry_categories (entry_id,category_id,position) values ('pinecone','05',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('pinecone','היכרות עם SQL, REST, אינדקסים והרשאות; לכלי מוצר מומלץ להתחיל ביסודות החיפוש הווקטורי.','תרחיש מוצע שלא הורץ: צוות Python/TypeScript מקים שירות המלצות ורוצה להימנע מתפעול מסד וקטורי. הוא בוחן Pinecone עם מסנני לקוח ומחיקה מדידה. בוחרים כשהשירות עומד בדרישות התקציב והאזור; בארגון .NET שרוצה SDK ספק פעיל או אירוח עצמי, בודקים תחילה Azure AI Search או Qdrant.','תכננו חוזה API עם ids, גרסאות ו־metadata והשוו עלות ותהליך מחיקה למסד עצמאי. ציינו במפורש מהי אסטרטגיית לקוח .NET בלי להסתמך על SDK מאורכב.','Python ו־TypeScript הם מסלולי SDK רשמיים. מאגר SDK .NET של הספק מאורכב מאז 03/07/2026; אין להציגו כתמיכה פעילה. C#/.NET יכולה לצרוך API או לקוח שנבדק בנפרד, ללא הבטחת SDK ספק נוכחי או שוויון יכולות. השירות עצמו אינו Legacy.','Azure AI Search למסלול חיפוש מנוהל רחב, Qdrant/Weaviate למסד בשליטה עצמית ו־pgvector ל־PostgreSQL. SDK מאורכב מחייב בדיקת סיכון, לא מסקנה אוטומטית שהשירות הופסק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pinecone',0,'שירות ולא שרת מקומי','Pinecone מנהלת תשתית מסד מאחורי API. מבחינים בין ניהול אינדקסים לבין פעולות נתונים וחיפוש. היישום עדיין אחראי למקורות, הרשאות, ייצוגים וקטוריים ותקינות התשובות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pinecone',1,'מודל מידע ומחזור חיים','שמרו מזהים יציבים ו־metadata לסינון, והגדירו איך מחלקים מידע בין משתמשים וארגונים. בדקו מה קורה ל־upsert, עדכונים ומחיקות בזמן כשל; אין להסיק מניהול התשתית שהמידע העסקי מסונכרן אוטומטית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pinecone',2,'מתי לבחור ומתי חלופה','מתאים לצוות שמעדיף שירות מנוהל ואינו רוצה להפעיל שרת וקטורי. אם המערכת חייבת אירוח עצמי, בחנו Qdrant/Weaviate; אם SQL קיים מספיק, pgvector מצמצמת העתקות; אם נדרש חיפוש ארגוני משולב ותמיכת .NET ספק פעילה, השוו Azure AI Search.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pinecone',3,'NET: לקוח מאורכב אינו שירות Legacy','הודעת הארכוב ב־GitHub ואזהרת Microsoft חשובות יותר מכותרת official שנותרה ב־README. אין לסמן את Pinecone עצמה Legacy בגלל SDK אחד. בדקו גרסת API וחוזה HTTP או לקוח חלופי לפני התחייבות מיישום C#.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pinecone',4,'עלות ומדידות','מסלול מסחרי דורש בדיקת מחיר, אזור, מכסות, פרטיות ועלויות העברת מידע. אין מאגר ליבת מסד פתוח מייצג; Stars של לקוח .NET אינם נתוני עניין של המסד. טענות ספק אינן benchmark בלתי תלוי.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('pinecone','should_know','כדאי להכיר את חלופת המסד המנוהל ולשקלל עלות, ספק ותמיכת .NET לפני בחירה.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('pinecone','שירות מסד וקטורי מנוהל; SDK .NET הרשמי מאורכב, והגישה מ־C# דורשת מסלול נבדק.','Python ו־TypeScript הם מסלולי SDK רשמיים. מאגר SDK .NET של הספק מאורכב מאז 03/07/2026; אין להציגו כתמיכה פעילה. C#/.NET יכולה לצרוך API או לקוח שנבדק בנפרד, ללא הבטחת SDK ספק נוכחי או שוויון יכולות. השירות עצמו אינו Legacy.','not_applicable','שירות מנוהל ללא מאגר ליבת מסד ציבורי מייצג; אין מדידה ממאגר SDK או דוגמאות.','2026-11-02');
