insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('chroma','היכרות עם SQL, REST, אינדקסים והרשאות; לכלי מוצר מומלץ להתחיל ביסודות החיפוש הווקטורי.','תרחיש מוצע שלא הורץ: צוות Python בונה כלי פנימי לחיפוש מסמכי צוות ורוצה להתחיל באחסון מתמשך מקומי ולהשוות בהמשך שרת. Chroma מספקת מסלול להשוואה זו. אם המוצר הארגוני ב־C# דורש SDK ספק פעיל, הרשאות מורכבות וקשרים ב־PostgreSQL, pgvector או Qdrant עשויות להתאים יותר לאחר בדיקה.','תכננו אותו אוסף במסלול persistent ובמסלול HTTP. בדקו שימור לאחר הפעלה מחדש, מחיקה וסינון, וציינו אילו יכולות תועדו רק במסלול אחד.','תיעוד הלקוחות מציג Python, TypeScript ו־Rust עבור מסלולי Cloud/HTTP, לצד שימוש מקומי לפי לקוח. לא אומת SDK רשמי ל־C#/.NET; צריכת HTTP או לקוח קהילתי מחייבות בדיקת תאימות נפרדת ואינן תמיכת .NET מקומית של הספק.','pgvector משלבת SQL, Qdrant/Weaviate מספקות SDK .NET רשמי, ו־LanceDB היא מועמדת נפרדת לאחסון retrieval משובץ ורב־מודלי שלא נוספה בסבב זה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('chroma',0,'מסלולי שימוש','מבחינים בין לקוח מקומי בזיכרון או באחסון מתמשך לבין חיבור לשרת או Cloud. המעבר בין מסלולים משנה אחריות על הרשאות, שמירה ותפעול; אין להבטיח זהות התנהגות בלי בדיקת גרסה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('chroma',1,'שליפה ויכולות לפי מסלול','סקירת המוצר הנוכחית מתארת dense/sparse/hybrid, מסמכים, טקסט וסינון. אין להסיק שכל אפשרות קיימת בכל גרסה מקומית או חבילת לקוח. בחרו תיעוד למסלול שנמדד ופרקו יצירת embeddings משליפה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('chroma',2,'מתי לבחור ומתי חלופה','מתאימה לבחינת retrieval במסלול מקומי/שרת עם API נוח לצוות Python/TS/Rust. אינה רק כלי ניסוי בזיכרון. אם למערכת .NET יש SQL וקשרים מרכזיים, התחילו בהשוואת pgvector; אם נדרש SDK .NET רשמי למסד ייעודי, בדקו Qdrant או Weaviate.');
insert into academy.entry_sections (entry_id,position,title,body) values ('chroma',3,'רישיון והיסטוריה','ליבת Chroma מתוארת כ־Apache-2.0; תנאי שירות Cloud נפרדים. תאריך החבילה 0.1.0 ב־2023 אינו תאריך השקת כל יכולת עדכנית. אין להצמיד שנת 2022 בלי מקור אירוע מאומת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('chroma',4,'איכות, שמירה ובטיחות','בדקו persistence, מחיקת מסמך, סינון והרשאות לפני שימוש בנתונים ארגוניים. הנוחות בהפעלת דוגמה אינה הוכחת אבטחה או יכולת גידול. השוו איכות ועלות על אותו אוסף ולא לפי מספר Stars.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('chroma','enrichment','העשרה שימושית להשוואת מסלול retrieval מקומי ושרת מול מסדים ייעודיים; אינה תרגול חובה נוסף לאחר pgvector/Qdrant.','2026-11-02','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('chroma','אחסון ושליפה במסלולי local, שרת וענן; לקוחות Python, TypeScript ו־Rust.','תיעוד הלקוחות מציג Python, TypeScript ו־Rust עבור מסלולי Cloud/HTTP, לצד שימוש מקומי לפי לקוח. לא אומת SDK רשמי ל־C#/.NET; צריכת HTTP או לקוח קהילתי מחייבות בדיקת תאימות נפרדת ואינן תמיכת .NET מקומית של הספק.','verified','המאגר הראשי של הפרויקט בלבד. צילום המחקר המאושר, לא דירוג איכות.','2026-11-02');
