insert into academy.entry_sections (entry_id,position,title,body) values ('qdrant',5,'לקוחות רשמיים וחיפוש משולב','הרשימה הרשמית כוללת Qdrant.Client ל־C#/.NET מעל gRPC, ולא רק Python ו־HTTP. Query API מאפשרת שילוב dense/sparse ומיזוג תוצאות; multivector הוא אפשרות ייצוג נפרדת. איכות שליפה, reranking והרשאות עדיין דורשות בדיקה עצמאית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('qdrant',6,'מתי לבחור ב־Qdrant','מתאימה לבחינת אחזור בשירות וקטורי נפרד עם Payload וסינון. אם הדרישה בעיקר joins וטרנזקציות קיימות ב־PostgreSQL, בחנו pgvector תחילה; אם רוצים שכבת חיפוש ארגוני מנוהל, השוו Azure AI Search. אין הבטחת ביצועים או recall בלי ניסוי.');
