insert into academy.category_guides (category_id,title,introduction,note) values ('05','איך ללמוד אחסון וחיפוש וקטורי?','מתחילים בעקרונות וב־baseline, משווים SQL למנוע ייעודי, ואז בוחנים חלופות לפי תפעול, חיפוש משולב ותמיכת שפות. לא חייבים ללמוד לעומק כל מוצר.','מסד וקטורי הוא רכיב בשליפה, לא מערכת RAG מלאה. SDK .NET רשמי, צריכת HTTP ולקוח היסטורי הם מצבים שונים; חשיבות ללימוד נפרדת מ־Stars.');
