-- Approved vector05-20261102-v1, V05-01 through V05-08. Content only.
begin isolation level serializable;
select pg_advisory_xact_lock(hashtext('academy-migrations'));
do $$ begin
 if (select max(version) from academy.schema_migrations) is distinct from 8 then raise exception 'Expected schema version 8'; end if;
 if (select count(*) from academy.entries e join academy.entry_categories c on c.entry_id=e.id where c.category_id='05')<>1 then raise exception 'Category changed since review'; end if;
 if not exists(select 1 from academy.entries e join academy.entry_categories c on c.entry_id=e.id where e.slug='qdrant' and e.id='qdrant' and e.revision=2 and e.kind='database' and e.publication_status='published' and c.category_id='05') then raise exception 'Reviewed Qdrant changed'; end if;
 if (select count(*) from academy.entry_sections where entry_id='qdrant')<>5 or exists(select 1 from academy.entry_releases where entry_id='qdrant') then raise exception 'Reviewed Qdrant facts changed'; end if;
 if exists(select 1 from academy.entries where slug in ('vector-search-fundamentals','pgvector','azure-ai-search','weaviate','milvus','pinecone','chroma') or lower(name) in ('חיפוש וקטורי — יסודות ובחירת אחסון','pgvector','azure ai search','weaviate','milvus','pinecone','chroma')) then raise exception 'Vector candidate already exists'; end if;
 if exists(select 1 from academy.repositories where url in ('https://github.com/pgvector/pgvector','https://github.com/weaviate/weaviate','https://github.com/milvus-io/milvus','https://github.com/chroma-core/chroma')) then raise exception 'Candidate repository already represented'; end if;
 if exists(select 1 from academy.category_guides where category_id='05') then raise exception 'Existing guide requires review'; end if;
end $$;
update academy.entries set summary='מסד ומנוע חיפוש לווקטורים עם Payload וסינון. תומך ב־dense, sparse ו־multivector ובשאילתות משולבות; היישום עדיין אחראי לייצוגים, הרשאות ומחזור חיי המקורות.',revision=revision+1,verified_at='2026-11-02',revision_note='תיקון מאושר V05-03: SDKs רשמיים, hybrid, דוגמת בחירה, אירוע v1.0 ומדידה; מקורות וסיווג קיימים נשמרו.' where slug='qdrant';
update academy.entry_lessons set example='תרחיש לימודי מוצע שלא הורץ: API של ASP.NET Core משתמש ב־Qdrant.Client מעל gRPC לחיפוש נהלים לפי משמעות ומזהי מסמך, עם Payload של ארגון וגרסה. בוחרים Qdrant כשמסד ייעודי וסינון hybrid מצדיקים הפרדת שירות; אם PostgreSQL כבר מספקת את האיכות והעומס הנדרשים, pgvector עשויה לפשט טרנזקציות וסנכרון.',language_support_note='ל־Qdrant לקוחות רשמיים Python, JavaScript/TypeScript, Rust, Go, Java ו־C#/.NET. חבילת Qdrant.Client משתמשת ב־gRPC; REST הוא מסלול נפרד. יש להתאים גרסאות לקוח ושרת, וב־.NET Framework הישן לבדוק מגבלות HTTP/2 במקום להניח תאימות מלאה.',alternatives_note='השוו pgvector כש־SQL וקשרים עסקיים מרכזיים, Weaviate/Milvus למסד ייעודי אחר ו־Azure AI Search לשירות חיפוש מנוהל. בחרו לפי מדידות, תמיכת לקוח, גיבוי והרשאות ולא לפי Stars.' where entry_id='qdrant';
update academy.catalog_facts set description='מסד וקטורי עם Payload, סינון וחיפוש משולב; SDK רשמי ל־C#/.NET מעל gRPC.',language_support_summary='ל־Qdrant לקוחות רשמיים Python, JavaScript/TypeScript, Rust, Go, Java ו־C#/.NET. חבילת Qdrant.Client משתמשת ב־gRPC; REST הוא מסלול נפרד. יש להתאים גרסאות לקוח ושרת, וב־.NET Framework הישן לבדוק מגבלות HTTP/2 במקום להניח תאימות מלאה.',reviewed_at='2026-11-02' where entry_id='qdrant';
delete from academy.entry_language_labels where entry_id='qdrant';
do $$ begin
 if (select count(*) from academy.entries where slug in ('vector-search-fundamentals','pgvector','azure-ai-search','weaviate','milvus','pinecone','chroma'))<>7 then raise exception 'Incomplete vector additions'; end if;
 if (select count(*) from academy.entry_categories where category_id='05')<>8 then raise exception 'Expected eight vector entries'; end if;
 if (select revision from academy.entries where slug='qdrant')<>3 then raise exception 'Qdrant revision missing'; end if;
end $$;
commit;
